type LocaleContextValue = {
  language: Language;
  setLanguage: (language: Language) => void;
  translate: (text: string) => string;
};

const LocaleContext = createContext<LocaleContextValue | null>(null);

export function LocaleProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>("EN");

  useEffect(() => {
    const saved = window.localStorage.getItem("jitours-language");
    const initial = languageNames.includes(saved as Language) ? saved as Language : "EN";
    setLanguageState(initial);
    document.documentElement.lang = initial.toLowerCase();
    document.documentElement.dir = initial === "AR" ? "rtl" : "ltr";
  }, []);

  function setLanguage(next: Language) {
    setLanguageState(next);
    window.localStorage.setItem("jitours-language", next);
    document.documentElement.lang = next.toLowerCase();
    document.documentElement.dir = next === "AR" ? "rtl" : "ltr";
  }

  function translate(text: string) {
    return translations[language][text] ?? extraTranslations[language]?.[text] ?? text;
  }

  return <LocaleContext.Provider value={{ language, setLanguage, translate }}>{children}</LocaleContext.Provider>;
}

export function useLocale() {
  const locale = useContext(LocaleContext);
  if (!locale) throw new Error("useLocale must be used within LocaleProvider.");
  return locale;
}

export function T({ children }: { children: string }) {
  const { translate } = useLocale();
  return <>{translate(children)}</>;
}
